function ProofZoomModal({ image, onClose }) {
  const [textScale, setTextScale] = useState(100);
  const [imageScale, setImageScale] = useState(100);
  const [bonusIndex, setBonusIndex] = useState(0);

  useEffect(() => {
    if (!image) return undefined;
    const handleKeyDown = (event) => event.key === 'Escape' && onClose();
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.body.style.overflow = previousOverflow;
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [image, onClose]);

  useEffect(() => {
    setTextScale(100);
    setImageScale(100);
    setBonusIndex(image?.bonusIndex || 0);
  }, [image]);

  if (!image) return null;

  const helperText = image.kind === 'toc'
    ? 'Versi teks agar daftar isi benar-benar terbaca di HP.'
    : image.kind === 'bonus'
      ? 'Preview HTML tajam — tidak memakai screenshot yang dibesarkan.'
      : 'Geser untuk melihat seluruh gambar.';

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 p-2 sm:p-6" role="dialog" aria-modal="true" aria-label={image.title} onClick={onClose}>
      <button type="button" onClick={onClose} className="absolute right-3 top-3 z-20 inline-flex h-11 w-11 items-center justify-center rounded-full bg-white text-black shadow-xl" aria-label="Tutup preview">
        <X className="h-6 w-6" />
      </button>

      <div className="flex max-h-[95vh] w-full max-w-6xl flex-col overflow-hidden rounded-2xl bg-white shadow-2xl" onClick={(event) => event.stopPropagation()}>
        <div className="flex flex-wrap items-center justify-between gap-3 border-b border-black/10 px-4 py-3 sm:px-5">
          <div>
            <p className="text-sm font-black text-neutral-900">{image.title}</p>
            <p className="mt-0.5 text-[11px] text-neutral-500">{helperText}</p>
          </div>
          {image.kind !== 'bonus' && (
            <div className="flex gap-1">
              {(image.kind === 'toc' ? [100, 125, 150] : [100, 150, 200]).map((scale) => (
                <button
                  key={scale}
                  type="button"
                  onClick={() => image.kind === 'toc' ? setTextScale(scale) : setImageScale(scale)}
                  className={`rounded-lg px-2.5 py-1.5 text-xs font-black ${(image.kind === 'toc' ? textScale : imageScale) === scale ? 'bg-primary text-white' : 'bg-neutral-100 text-neutral-700'}`}
                >
                  {scale}%
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="overflow-auto bg-[#f4f1eb] p-3 sm:p-5">
          {image.kind === 'toc' ? (
            <div className="mx-auto max-w-5xl rounded-xl bg-white p-4 sm:p-7" style={{ fontSize: `${textScale}%` }}>
              <div className="mb-5 flex items-end justify-between border-b-2 border-primary/20 pb-3">
                <h3 className="text-2xl font-black">DAFTAR ISI</h3>
                <span className="text-xs font-bold text-neutral-500">Daftar Pustaka · 549</span>
              </div>
              <div className="grid gap-5 md:grid-cols-2">
                {TOC_CHAPTERS.map((chapter) => (
                  <section key={chapter.title} className="break-inside-avoid rounded-xl border border-black/10 p-3">
                    <div className="mb-2 flex items-center justify-between gap-3 font-black text-primary">
                      <span>{chapter.title}</span><span>{chapter.page}</span>
                    </div>
                    <ol className="space-y-1.5 text-neutral-800">
                      {chapter.items.map(([title, page], index) => (
                        <li key={title} className="grid grid-cols-[1.3rem_1fr_auto] gap-1.5 leading-snug">
                          <span className="font-bold text-neutral-400">{index + 1}.</span><span>{title}</span><span className="font-bold text-neutral-600">{page}</span>
                        </li>
                      ))}
                    </ol>
                  </section>
                ))}
              </div>
            </div>
          ) : image.kind === 'bonus' ? (
            <BonusHtmlPreview activeBonus={bonusIndex} onSelect={setBonusIndex} />
          ) : (
            <img src={image.src} alt={image.alt} style={{ width: `${imageScale}%`, maxWidth: 'none' }} className="mx-auto h-auto min-w-full rounded-xl bg-white object-contain" />
          )}
        </div>
      </div>
    </div>
  );
}

