function PanglimaVariantCheckoutButton({ variant, className = '' }) {
  const config = PANGLIMA_PROFESSION_VARIANTS[variant];

  const handleCheckout = () => {
    if (typeof window.fbq === 'function') {
      window.fbq('trackCustom', 'CheckoutClick', {
        content_name: config.badge,
        destination_url: PANGLIMA_CHECKOUT_URL,
        source_page: window.location.pathname,
        variant: config.menuLabel,
      });

      window.fbq('track', 'InitiateCheckout', {
        content_name: config.badge,
        content_type: 'product',
        content_ids: [config.contentId],
        value: PANGLIMA_PRICE_VALUE,
        currency: 'IDR',
        num_items: 1,
      });
    }

    if (typeof window.gtag === 'function') {
      window.gtag('event', 'checkout_click', {
        item_name: config.badge,
        item_variant: config.menuLabel,
        value: PANGLIMA_PRICE_VALUE,
        currency: 'IDR',
        destination_url: PANGLIMA_CHECKOUT_URL,
      });
    }
  };

  return (
    <a
      href={PANGLIMA_CHECKOUT_URL}
      target="_blank"
      rel="noopener noreferrer"
      onClick={handleCheckout}
      className={`inline-flex min-h-[54px] w-full items-center justify-center gap-2 rounded-xl bg-[hsl(var(--gold))] px-5 text-center text-sm font-black text-[hsl(var(--ink))] shadow-lg shadow-black/15 transition hover:-translate-y-0.5 hover:brightness-105 active:translate-y-0 ${className}`}
    >
      {config.checkoutLabel}
      <ArrowRight className="h-5 w-5" />
    </a>
  );
}

