function loadAffiliateRegistry() {
  if (typeof window === 'undefined') {
    return Promise.resolve(DYNAMIC_AFFILIATE_PARTNERS);
  }

  if (affiliateRegistryPromise) return affiliateRegistryPromise;

  if (!AFFILIATE_API_ENDPOINT.startsWith('https://script.google.com/')) {
    return Promise.resolve(DYNAMIC_AFFILIATE_PARTNERS);
  }

  affiliateRegistryPromise = new Promise((resolve) => {
    const callbackName = `__panglimaAffiliateRegistry_${Date.now()}_${Math.random()
      .toString(36)
      .slice(2)}`;
    const script = document.createElement('script');
    const timeout = window.setTimeout(() => cleanup({}), 10000);

    function cleanup(payload) {
      window.clearTimeout(timeout);
      try {
        delete window[callbackName];
      } catch (error) {
        window[callbackName] = undefined;
      }
      script.remove();

      const partners = payload?.partners && typeof payload.partners === 'object'
        ? payload.partners
        : {};

      DYNAMIC_AFFILIATE_PARTNERS = partners;
      resolve(DYNAMIC_AFFILIATE_PARTNERS);
    }

    window[callbackName] = (payload) => cleanup(payload);
    script.onerror = () => cleanup({});
    script.src = `${AFFILIATE_API_ENDPOINT}?action=registry&callback=${encodeURIComponent(callbackName)}&t=${Date.now()}`;
    document.head.appendChild(script);
  }).finally(() => {
    affiliateRegistryPromise = null;
  });

  return affiliateRegistryPromise;
}

function getAffiliatePartners() {
  return {
    ...AFFILIATE_PARTNERS,
    ...DYNAMIC_AFFILIATE_PARTNERS,
  };
}

function getAffiliatePartnerBySlug(slug = '') {
  return getAffiliatePartners()[normalizeAffiliateSlug(slug)] || null;
}

function normalizeAffiliateSlug(value = '') {
  return String(value).trim().toLowerCase();
}

function normalizeAffiliateCode(value = '') {
  return String(value).trim().toUpperCase();
}

function generateAffiliateCode(name = '', whatsapp = '') {
  const firstName = String(name).trim().split(/\s+/)[0] || '';
  const firstThreeLetters = firstName
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z]/g, '')
    .slice(0, 3)
    .toUpperCase()
    .padEnd(3, 'X');

  const phoneDigits = String(whatsapp || '').replace(/\D/g, '');
  const lastThreeDigits = phoneDigits.slice(-3).padStart(3, '0');

  return `${firstThreeLetters}${lastThreeDigits}`;
}

function getAffiliateCode(partner) {
  if (!partner) return '';
  const explicitCode = normalizeAffiliateCode(partner.code || '');
  if (explicitCode) return explicitCode;
  return generateAffiliateCode(partner.name, partner.whatsapp || SITE.whatsapp);
}


function isActiveAffiliatePartner(partner) {
  if (!partner || partner.active === false) return false;
  if (partner.isDemo) return true;
  return !partner.status || String(partner.status).toUpperCase() === 'APPROVED';
}

function isAffiliateCheckoutReady(partner) {
  if (!isActiveAffiliatePartner(partner)) return false;
  if (partner.isDemo) return true;

  const checkout = String(partner.checkoutUrl || '').trim();
  if (!checkout) return false;
  if (checkout === PANGLIMA_DEFAULT_CHECKOUT_URL) return false;
  if (checkout.includes('PASTE_LINK_')) return false;

  return true;
}

function findAffiliatePartnerByCode(code = '') {
  const normalizedCode = normalizeAffiliateCode(code);
  if (!normalizedCode) return null;

  for (const [slug, partner] of Object.entries(getAffiliatePartners())) {
    if (
      isActiveAffiliatePartner(partner) &&
      getAffiliateCode(partner) === normalizedCode
    ) {
      return { slug, partner };
    }
  }

  return null;
}

function storeAffiliateReferral(slug, partner, source = 'unknown') {
  if (typeof window === 'undefined') return;
  if (!slug || !isActiveAffiliatePartner(partner)) return;

  const payload = {
    slug: normalizeAffiliateSlug(slug),
    code: getAffiliateCode(partner),
    name: partner.name,
    source,
    savedAt: Date.now(),
  };

  try {
    window.localStorage.setItem(
      AFFILIATE_REF_STORAGE_KEY,
      JSON.stringify(payload)
    );
  } catch (error) {
    // Referral halaman aktif tetap berjalan walau localStorage diblokir browser.
  }
}

function getStoredAffiliateReferral() {
  if (typeof window === 'undefined') return null;

  try {
    const raw = window.localStorage.getItem(AFFILIATE_REF_STORAGE_KEY);
    if (!raw) return null;

    const parsed = JSON.parse(raw);
    const savedAt = Number(parsed?.savedAt || 0);
    const maxAge = AFFILIATE_REF_VALID_DAYS * 24 * 60 * 60 * 1000;

    if (!savedAt || Date.now() - savedAt > maxAge) {
      window.localStorage.removeItem(AFFILIATE_REF_STORAGE_KEY);
      return null;
    }

    return parsed;
  } catch (error) {
    return null;
  }
}

function AffiliateReferralCapture() {
  const location = useLocation();

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const params = new URLSearchParams(location.search);
    const referralCode = params.get('ref');
    if (!referralCode) return;

    let cancelled = false;

    const captureReferral = async () => {
      await loadAffiliateRegistry();
      if (cancelled) return;

      const match = findAffiliatePartnerByCode(referralCode);
      if (!match) return;

      storeAffiliateReferral(match.slug, match.partner, 'query-ref');

      if (typeof window.fbq === 'function') {
        window.fbq('trackCustom', 'AffiliateReferralCaptured', {
          affiliate_code: getAffiliateCode(match.partner),
          affiliate_name: match.partner.name,
          affiliate_slug: match.slug,
          source_page: location.pathname,
        });
      }

      if (typeof window.gtag === 'function') {
        window.gtag('event', 'affiliate_referral_captured', {
          affiliate_code: getAffiliateCode(match.partner),
          affiliate_name: match.partner.name,
          affiliate_slug: match.slug,
          source_page: location.pathname,
        });
      }
    };

    captureReferral();

    return () => {
      cancelled = true;
    };
  }, [location.pathname, location.search]);

  return null;
}

function AffiliateReferralBridge() {
  useEffect(() => {
    const handleClick = async (event) => {
      const link = event.target?.closest?.('a[href]');
      if (!link) return;

      const stored = getStoredAffiliateReferral();
      if (!stored?.slug) return;

      await loadAffiliateRegistry();
      const partner = getAffiliatePartnerBySlug(stored.slug);
      if (!isActiveAffiliatePartner(partner)) return;
      if (!isAffiliateCheckoutReady(partner)) return;

      let targetUrl;
      try {
        targetUrl = new URL(link.href, window.location.origin);
      } catch (error) {
        return;
      }

      const isPanglimaCheckout =
        targetUrl.hostname === 'lynk.id' &&
        targetUrl.pathname.includes('/9rov84wv3grz');

      if (!isPanglimaCheckout) return;

      const destination = partner.checkoutUrl;
      if (!destination || destination === link.href) return;

      event.preventDefault();

      trackAffiliateEvent(
        'CHECKOUT_CLICK',
        partner,
        stored.slug,
        destination
      );

      if (typeof window.fbq === 'function') {
        window.fbq('trackCustom', 'AffiliateCheckoutClick', {
          affiliate_code: getAffiliateCode(partner),
          affiliate_name: partner.name,
          source_page: window.location.pathname,
        });
      }

      if (typeof window.gtag === 'function') {
        window.gtag('event', 'affiliate_checkout_click', {
          affiliate_code: getAffiliateCode(partner),
          affiliate_name: partner.name,
          source_page: window.location.pathname,
        });
      }

      window.location.href = destination;
    };

    document.addEventListener('click', handleClick, true);

    return () => {
      document.removeEventListener('click', handleClick, true);
    };
  }, []);

  return null;
}

