/* =========================================================
   AFFILIATE QUERY GATEWAY — HOSTINGER SAFE
   Menggunakan root path agar tidak bergantung pada deep-link
   rewrite Hostinger. Contoh:
   /?affiliate=ratna
   /?affiliate=ratna&kit=1
   ========================================================= */
function AffiliateQueryGateway() {
  const location =
    useLocation();

  const params =
    new URLSearchParams(
      location.search
    );

  const portalMode =
    String(
      params.get('portal') ||
      ''
    )
      .trim()
      .toLowerCase();

  const affiliateSlug =
    normalizeAffiliateSlug(
      params.get(
        'affiliate'
      ) || ''
    );

  const isKit =
    params.get('kit') ===
    '1';

  const [
    partner,
    setPartner,
  ] =
    useState(
      () =>
        getAffiliatePartnerBySlug(
          affiliateSlug
        )
    );

  const [
    registryLoading,
    setRegistryLoading,
  ] =
    useState(
      Boolean(
        affiliateSlug
      ) &&
      !partner
    );

  useEffect(
    () => {
      if (
        !affiliateSlug
      ) {
        return undefined;
      }

      let cancelled =
        false;

      const syncPartner =
        async () => {
          if (
            !getAffiliatePartnerBySlug(
              affiliateSlug
            )
          ) {
            setRegistryLoading(
              true
            );
          }

          await loadAffiliateRegistry();

          if (
            cancelled
          ) {
            return;
          }

          setPartner(
            getAffiliatePartnerBySlug(
              affiliateSlug
            )
          );

          setRegistryLoading(
            false
          );
        };

      syncPartner();

      return () => {
        cancelled =
          true;
      };
    },
    [
      affiliateSlug,
    ]
  );

  /*
   * STEP 10B:
   * Portal dicek SETELAH seluruh hooks dipanggil
   * agar Rules of Hooks React tetap aman.
   */
  if (
    portalMode ===
    'affiliate'
  ) {
    return (
      <AffiliatePortalPage />
    );
  }

  if (
    !affiliateSlug
  ) {
    return (
      <HomePage />
    );
  }

  if (
    registryLoading
  ) {
    return (
      <main className="flex min-h-[60vh] items-center justify-center bg-white px-5">
        <div className="text-center">

          <div className="mx-auto h-9 w-9 animate-spin rounded-full border-4 border-neutral-200 border-t-red-600" />

          <p className="mt-4 text-sm font-semibold text-neutral-600">
            Memuat halaman Partner Panglima…
          </p>

        </div>
      </main>
    );
  }

  if (
    !isActiveAffiliatePartner(
      partner
    )
  ) {
    return (
      <NotFoundPage />
    );
  }

  if (
    isKit
  ) {
    return (
      <AffiliateMarketingKitPage
        initialPartner={
          partner
        }
        initialSlug={
          affiliateSlug
        }
      />
    );
  }

  return (
    <AffiliateSalesPage
      initialPartner={
        partner
      }
      initialSlug={
        affiliateSlug
      }
    />
  );
}




